      if (!trimmed) return 'Email address is required.';
      if (!EMAIL_RE.test(trimmed)) return 'Please enter a valid email address (e.g. you@example.com).';
    }

    if (id === 'phone' && trimmed) {
      if (!PHONE_RE.test(trimmed))
        return 'Please use a valid format, e.g. +1 (555) 000-0000 or 555-000-0000.';
    }

    return '';
  }

  /** Wire up blur-time validation for immediate feedback after leaving a field. */
  ['full-name', 'email', 'phone'].forEach((fieldId) => {
    const input = document.getElementById(fieldId);
    const errorEl = document.getElementById(`${fieldId}-error`);

    input.addEventListener('blur', () => {
      const msg = validateField(input);
      setError(input, errorEl, msg);
    });

    // Clear error as soon as the user starts correcting the field
    input.addEventListener('input', () => {
      if (input.getAttribute('aria-invalid') === 'true') {
        const msg = validateField(input);
        setError(input, errorEl, msg);
      }
    });
  });

  form.addEventListener('submit', (e) => {
    e.preventDefault();

    const fields = [
      { input: document.getElementById('full-name'), errorEl: document.getElementById('full-name-error') },
      { input: document.getElementById('email'),     errorEl: document.getElementById('email-error')     },
      { input: document.getElementById('phone'),     errorEl: document.getElementById('phone-error')     },
    ];

    let firstInvalid = null;

    fields.forEach(({ input, errorEl }) => {
      const msg = validateField(input);
      setError(input, errorEl, msg);
      if (msg && !firstInvalid) firstInvalid = input;
    });

    if (firstInvalid) {
      // Move focus to the first invalid field (WCAG 3.3.1)
      firstInvalid.focus();
      formStatus.textContent = 'Please fix the errors below and try again.';
      return;
    }

    // Submission succeeded — show success state
    form.hidden = true;
    successMessage.hidden = false;
    successMessage.querySelector('h2').focus();
    formStatus.textContent = '';
  });
